import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '@/contexts/AuthContext'
import { createGearRepository } from '@/lib/gearRepository'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { CheckCircle, AlertCircle, Info, Package, X, Weight, Tag, ArrowLeft, Loader2 } from 'lucide-react'
import { StatTile } from '@/components/ui/stat-tile'
import { GearTable } from '@/components/gear/GearTable'
import { formatWeightForDisplay, formatWeightWithUnit } from '@/utils/weight'
import type { ParsedGearItem } from '@/utils/parser'
import type { GearItem } from '@/types/database'

interface ImportPreviewProps {
  items: ParsedGearItem[]
  newItems: ParsedGearItem[]
  duplicates: ParsedGearItem[]
  errors?: string[]
  warnings?: string[]
  metadata?: any
  onCancel: () => void
  className?: string
}

export function ImportPreview({
  items,
  newItems,
  duplicates,
  errors = [],
  metadata,
  onCancel,
  className
}: ImportPreviewProps) {
  const { user } = useAuth()
  const navigate = useNavigate()
  const [isImporting, setIsImporting] = useState(false)
  const [importError, setImportError] = useState<string | null>(null)
  const newItemsWeight = newItems.reduce((sum, item) => sum + item.weight_g, 0)
  const newCategories = new Set(newItems.map(item => item.item_type))

  const handleImport = async () => {
    if (!user) {
      setImportError('User not authenticated')
      return
    }

    setIsImporting(true)
    setImportError(null)

    try {
      const gearRepository = createGearRepository(user.id)

      // Convert newItems to the format expected by the repository  
      const itemsToCreate = newItems.map(item => ({
        item_type: item.item_type,
        description: item.description,
        brand: item.brand,
        model: item.model,
        consumable: item.consumable,
        price: item.price,
        weight_g: item.weight_g,
        weight_unit_display: item.weight_unit_display,
        notes: item.notes,
        image_url: item.image_url,
        url: item.url
      }))

      // Use createMany for bulk insert
      await gearRepository.createMany(itemsToCreate)

      // Redirect to gear closet
      navigate('/gear')
    } catch (error) {
      console.error('Failed to import items:', error)
      setImportError(error instanceof Error ? error.message : 'Unknown error occurred')
    } finally {
      setIsImporting(false)
    }
  }

  // Convert ParsedGearItem to GearItem format for GearTable - combine new items and duplicates
  const convertToGearItem = (item: ParsedGearItem, index: number, isDuplicate: boolean = false): GearItem => ({
    id: `preview-${isDuplicate ? 'duplicate' : 'new'}-${index}`,
    user_id: '',
    item_type: item.item_type,
    description: item.description,
    brand: item.brand || null,
    model: item.model || null,
    consumable: item.consumable,
    price: item.price || null,
    weight_g: item.weight_g,
    weight_unit_display: item.weight_unit_display,
    notes: item.notes || null,
    image_url: item.image_url || null,
    url: item.url || null,
    created_at: '',
    updated_at: ''
  })

  // Combine new items and duplicates for display
  const allItemsForTable: GearItem[] = [
    ...newItems.map((item, index) => convertToGearItem(item, index, false)),
    ...duplicates.map((item, index) => convertToGearItem(item, index, true))
  ]

  // Function to check if an item is a duplicate
  const isDuplicateItem = (item: GearItem): boolean => {
    return item.id.includes('duplicate')
  }

  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <CardTitle className="flex items-center gap-2 text-lg">
          <CheckCircle className="h-4 w-4 text-green-600" />
          Import Preview
          {metadata?.listName && (
            <span className="text-sm font-normal text-muted-foreground">• {metadata.listName}</span>
          )}
        </CardTitle>
        <CardDescription className="text-sm">
          {newItems.length > 0 ? (
            <>
              {newItems.length} new items ready to import
              {duplicates.length > 0 && (
                <span className="text-muted-foreground"> • {duplicates.length} duplicates skipped</span>
              )}
            </>
          ) : (
            "No new items to import (all items already exist)"
          )}
        </CardDescription>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* No New Items Special Case */}
        {newItems.length === 0 && duplicates.length > 0 && (
          <Alert>
            <Info className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">All items already exist in your gear library</div>
              <div className="text-sm">
                We found {duplicates.length} items from your import, but they all match items you already have.
                You can go back to import different data or close this dialog.
              </div>
            </AlertDescription>
          </Alert>
        )}

        {/* Errors */}
        {errors.length > 0 && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Import Errors:</div>
              <ul className="list-disc list-inside space-y-1">
                {errors.map((error, i) => (
                  <li key={i} className="text-sm">{error}</li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        )}

        {/* Summary Stats - Compact */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-2">
          <StatTile
            title="New Items"
            value={newItems.length}
            description="items to import"
            icon={Package}
            iconColor="success"
            compact={true}
          />
          <StatTile
            title="Duplicates"
            value={duplicates.length}
            description="skipped"
            icon={X}
            iconColor="warning"
            compact={true}
          />
          <StatTile
            title="New Weight"
            value={formatWeightForDisplay(newItemsWeight)}
            description="total weight"
            icon={Weight}
            iconColor="info"
            compact={true}
          />
          <StatTile
            title="Categories"
            value={newCategories.size}
            description="gear types"
            icon={Tag}
            iconColor="primary"
            compact={true}
          />
        </div>

        {/* All Items Table (New + Duplicates) */}
        {allItemsForTable.length > 0 && (
          <div className="space-y-2">
            <h4 className="font-medium text-sm">
              {newItems.length > 0 && duplicates.length > 0 
                ? `${newItems.length} New Items + ${duplicates.length} Duplicates`
                : newItems.length > 0
                ? 'New Items to Import'
                : 'Duplicate Items (Already Exist)'}
            </h4>
            <div className="max-h-48 overflow-y-auto">
              <GearTable
                items={allItemsForTable}
                viewMode="compact"
                weightUnit="g" // Show in grams for now (could be made configurable)
                onEdit={() => {}} // No editing in preview
                onDelete={() => {}} // No deleting in preview
                showActions={false}
                isDuplicate={isDuplicateItem}
              />
            </div>
          </div>
        )}

        {/* Duplicates Preview */}
        {duplicates.length > 0 && (
          <div>
            <h4 className="font-medium mb-2 text-orange-600 text-sm">Duplicate Items (skipped)</h4>
            <div className="space-y-1 max-h-24 overflow-y-auto">
              {duplicates.slice(0, 2).map((item, i) => (
                <div key={i} className="flex items-center justify-between p-2 bg-orange-50 border border-orange-200 rounded text-xs">
                  <div className="flex-1 truncate">
                    <div className="font-medium text-orange-800 truncate">{item.description}</div>
                    <div className="text-orange-600">
                      {item.item_type} • {formatWeightWithUnit(item.weight_g, item.weight_unit_display)}
                    </div>
                  </div>
                  <span className="text-xs bg-orange-200 text-orange-800 px-1 py-0.5 rounded flex-shrink-0">Duplicate</span>
                </div>
              ))}
              {duplicates.length > 2 && (
                <div className="text-center text-xs text-orange-600 py-1">
                  ... and {duplicates.length - 2} more
                </div>
              )}
            </div>
          </div>
        )}

        {/* Import Error */}
        {importError && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Import Failed:</div>
              <div className="text-sm">{importError}</div>
            </AlertDescription>
          </Alert>
        )}

        {/* Actions */}
        <div className="flex justify-center gap-2 pt-2">
          {newItems.length > 0 ? (
            <>
              <Button onClick={handleImport} disabled={isImporting} size="sm">
                {isImporting ? (
                  <>
                    <Loader2 className="h-3 w-3 mr-1 animate-spin" />
                    Importing...
                  </>
                ) : (
                  `Import ${newItems.length} Items`
                )}
              </Button>
              <Button variant="outline" onClick={onCancel} disabled={isImporting} size="sm">
                Back
              </Button>
            </>
          ) : (
            <Button variant="outline" onClick={onCancel} size="sm">
              Back to Import
            </Button>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

