describe('ImportPreview', () => {
  const mockOnCancel = vi.fn()

  const sampleItems: ParsedGearItem[] = [
    {
      description: 'Test Backpack',
      brand: 'Test Brand',
      model: null,
      weight_g: 1500,
      weight_unit_display: 'g',
      item_type: 'Shelter',
      consumable: false,
      price: null,
      notes: null,
      image_url: null,
      url: null
    },
    {
      description: 'Test Jacket',
      brand: 'Another Brand',
      model: null,
      weight_g: 400,
      weight_unit_display: 'g',
      item_type: 'Clothing',
      consumable: false,
      price: null,
      notes: null,
      image_url: null,
      url: null
    }
  ]

  beforeEach(() => {
    vi.clearAllMocks()
  })

  describe('Basic Rendering', () => {
    it('should render import preview with items', () => {
      render(
        <ImportPreview
          items={sampleItems}
          newItems={sampleItems}
          duplicates={[]}
          onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText('Import Preview')).toBeInTheDocument()
      expect(screen.getByText('2 new items ready to import')).toBeInTheDocument()
    })

    it('should display weight in grams when under 1000g', () => {
      const lightItems: ParsedGearItem[] = [
        {
          description: 'Light Item',
          brand: 'Test Brand',
          model: null,
          weight_g: 250,
          weight_unit_display: 'g',
          item_type: 'Other',
          consumable: false,
          price: null,
          notes: null,
          image_url: null,
          url: null
        }
      ]

      render(
        <ImportPreview
          items={lightItems}
          newItems={lightItems}
          duplicates={[]}
          onCancel={mockOnCancel}
        />
      )

      expect(screen.getAllByText('250g')[0]).toBeInTheDocument()
    })
  })

  describe('No New Items Case', () => {
    it('should show special message when no new items but has duplicates', () => {
      render(
        <ImportPreview
          items={sampleItems}
          newItems={[]}
          duplicates={sampleItems}
