        <ImportPreview
          items={sampleItems}
          newItems={[]}
          duplicates={sampleItems}
                    onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText('No new items to import (all items already exist)')).toBeInTheDocument()
    })
