      expect(screen.getAllByText('Test Backpack')[0]).toBeInTheDocument()
    })

    it('should show duplicate items with orange styling', () => {
      const newItems = [sampleItems[0]]
      const duplicates = [sampleItems[1]]

      render(
        <ImportPreview
          items={sampleItems}
          newItems={newItems}
          duplicates={duplicates}
                    onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText('Duplicates')).toBeInTheDocument()
      // Check that duplicate items are displayed
      expect(screen.getAllByText('Test Jacket')[0]).toBeInTheDocument()
    })
  })

  describe('Clean Warnings Display', () => {
    it('should show summary information without ugly lists', () => {
      const warnings = [
        '1 items skipped as duplicates (already exist in your gear library)',
        '1 new items ready to import'
      ]

      render(
        <ImportPreview
          items={sampleItems}
          newItems={[sampleItems[0]]}
          duplicates={[sampleItems[1]]}
          warnings={warnings}
                    onCancel={mockOnCancel}
        />
      )

      // Component shows its own summary in the description
      expect(screen.getByText('1 new items ready to import')).toBeInTheDocument()
      expect(screen.getByText(/duplicates skipped/)).toBeInTheDocument()

      // Should NOT show individual item listings like "• Skipped: Item Name"
      expect(screen.queryByText(/• Skipped:/)).not.toBeInTheDocument()
    })
  })
})

import { memo, useMemo } from 'react'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Edit2, Trash2, MoreHorizontal, Copy, ChevronUp, ChevronDown, ChevronsUpDown, FileText } from 'lucide-react'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'
import type { ViewMode } from '@/pages/GearPage'

export type SortField = 'label' | 'item_type' | 'weight_g'
export type SortDirection = 'asc' | 'desc'

interface GearTableProps {
  items: GearItem[]
  viewMode: ViewMode
  weightUnit?: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  showActions?: boolean
  // Optional function to check if an item is a duplicate (for import preview)
  isDuplicate?: (item: GearItem) => boolean
  // Legacy sorting props (now optional and can be omitted)
  sortField?: SortField
  sortDirection?: SortDirection
  onSort?: (field: SortField) => void
}

export const GearTable = memo(function GearTable({
  items,
  viewMode,
  weightUnit = 'g',
  onEdit,
  onDelete,
  showActions = true,
  isDuplicate,
  sortField,
  sortDirection,
  onSort
}: GearTableProps) {
  const isCompact = viewMode === 'compact' || !showActions

  // Memoize summary calculations
  const totalWeight = useMemo(() => 
    items.reduce((sum, item) => sum + item.weight_g, 0), [items]
  )

  const getSortIcon = (field: SortField) => {
    if (sortField !== field) {
      return <ChevronsUpDown className="ml-1 h-3 w-3 text-muted-foreground/50" />
    }
    return sortDirection === 'asc'
      ? <ChevronUp className="ml-1 h-3 w-3" />
      : <ChevronDown className="ml-1 h-3 w-3" />
  }

  return (
    <div className="bg-white rounded-lg border border-border/40 overflow-hidden">
      <Table>
        <TableHeader>
          <TableRow className={isCompact ? 'h-8' : 'h-10'}>
            <TableHead
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium cursor-pointer hover:bg-accent/50`}
              onClick={() => onSort?.('label')}
            >
              <div className="flex items-center">
                Item
                {getSortIcon('label')}
              </div>
            </TableHead>
            <TableHead
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium cursor-pointer hover:bg-accent/50 hidden sm:table-cell`}
              onClick={() => onSort?.('item_type')}
            >
              <div className="flex items-center">
                Item Type
                {getSortIcon('item_type')}
              </div>
            </TableHead>
            <TableHead
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium text-right cursor-pointer hover:bg-accent/50 hidden sm:table-cell`}
              onClick={() => onSort?.('weight_g')}
            >
              <div className="flex items-center justify-end">
                Weight
                {getSortIcon('weight_g')}
              </div>
            </TableHead>
            {!isCompact && (
              <TableHead className="text-sm font-medium hidden sm:table-cell">
                Properties
              </TableHead>
            )}
            {showActions && (
              <TableHead className="text-right">
                <span className="sr-only">Actions</span>
              </TableHead>
            )}
          </TableRow>
        </TableHeader>
        <TableBody>
          {items.map((item) => {
            const isItemDuplicate = isDuplicate?.(item) ?? false
            return (
            <TableRow
              key={item.id}
              className={`transition-colors ${
                isCompact ? 'h-10' : 'h-14'
              } ${
                isItemDuplicate 
                  ? 'bg-orange-50/50 hover:bg-orange-100/70 opacity-60' 
                  : 'hover:bg-accent/50'
              }`}
            >
              <TableCell className={isCompact ? 'py-1' : 'py-2'}>
                <div className={isCompact ? 'space-y-0' : 'space-y-1'}>
                  <div className={`${isCompact ? 'text-sm' : 'text-base'}`}>
                    {item.url ? (
                      <a
                        href={item.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-primary hover:underline"
                      >
                        {item.description || 'Untitled Item'}
                      </a>
                    ) : (
                      item.description || 'Untitled Item'
                    )}
                  </div>
                  {(item.model || item.description) && (
                    <div className={`text-muted-foreground ${isCompact ? 'text-xs' : 'text-sm'}`}>
                      {item.model || item.description}
                    </div>
                  )}
                  {!isCompact && item.brand && (
                    <div className="text-xs text-muted-foreground">
                      {item.brand}
                    </div>
                  )}
                  {/* Mobile-only: Show category, weight, and properties inline */}
                  <div className="sm:hidden text-xs text-muted-foreground mt-1">
                    {item.item_type} • {formatWeightWithUnit(item.weight_g, weightUnit)}
                    {item.consumable && <span> • Consumable</span>}
                    {isItemDuplicate && (
                      <span className="text-orange-600 font-medium"> • Duplicate</span>
                    )}
                  </div>
                </div>
              </TableCell>
              <TableCell className={`${isCompact ? 'py-1' : 'py-2'} hidden sm:table-cell`}>
                <div className="flex items-center gap-1">
                  <Badge variant="outline" className={isCompact ? 'text-xs py-0' : ''}>
                    {item.item_type}
                  </Badge>
                  {isItemDuplicate && (
                    <Badge variant="secondary" className="text-xs bg-orange-200 text-orange-800 border-orange-300">
                      Duplicate
                    </Badge>
                  )}
                </div>
              </TableCell>
              <TableCell className={`text-right ${isCompact ? 'py-1 text-sm' : 'py-2'} hidden sm:table-cell`}>
                {formatWeightWithUnit(item.weight_g, weightUnit)}
              </TableCell>
              {!isCompact && (
                <TableCell className="py-2 hidden sm:table-cell">
                  <div className="flex items-center gap-1">
                    {item.consumable && (
                      <Badge variant="secondary" className="text-xs">
                        Consumable
                      </Badge>
                    )}
                    {item.notes ? (
                      <div className="group relative">
                        <FileText className="h-3 w-3 text-muted-foreground cursor-help" />
                        <div className="absolute z-10 hidden group-hover:block bottom-full left-0 mb-2 w-64 p-2 bg-popover text-popover-foreground text-xs rounded-md shadow-md border">
                          {item.notes}
                        </div>
                      </div>
                    ) : null}
                  </div>
                </TableCell>
              )}
              {showActions && (
                <TableCell className={`text-right ${isCompact ? 'py-1' : 'py-2'}`}>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button
                        variant="ghost"
                        size={isCompact ? 'sm' : 'default'}
                        className="h-8 w-8 p-0"
                      >
                        <span className="sr-only">Open menu</span>
                        <MoreHorizontal className={isCompact ? 'h-3 w-3' : 'h-4 w-4'} />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuItem
                        onClick={() => onEdit(item)}
                        className="cursor-pointer"
                      >
                        <Edit2 className="mr-2 h-4 w-4" />
                        Edit
                      </DropdownMenuItem>
                      <DropdownMenuItem
                        onClick={() => {
                          // Clone functionality - use object destructuring for type safety
                          const { id, created_at, updated_at, user_id, ...cloneData } = item
                          // Create a new item with the cloned data
                          const newItem: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'> = cloneData
                          // Since we're using onEdit for duplicate, we need to pass a full GearItem
                          // The parent will handle this as a create operation
                          onEdit({ ...newItem, description: `${newItem.description || 'Item'} (Copy)` } as GearItem)
                        }}
                        className="cursor-pointer"
                      >
                        <Copy className="mr-2 h-4 w-4" />
                        Duplicate
                      </DropdownMenuItem>
                      <DropdownMenuSeparator />
                      <DropdownMenuItem
                        onClick={() => onDelete(item)}
                        className="cursor-pointer text-destructive focus:text-destructive"
                      >
                        <Trash2 className="mr-2 h-4 w-4" />
                        Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </TableCell>
              )}
            </TableRow>
            )
          })}
          {/* Summary Row */}
          {items.length > 0 && (
            <TableRow className="bg-muted/50 border-t-2 font-medium">
              <TableCell className={`${isCompact ? 'py-2 text-sm' : 'py-3'}`}>
                Total ({items.length} items)
              </TableCell>
              <TableCell className="hidden sm:table-cell" />
              <TableCell className={`text-right ${isCompact ? 'py-2 text-sm' : 'py-3'} hidden sm:table-cell`}>
                {formatWeightWithUnit(totalWeight, weightUnit)}
              </TableCell>
              {!isCompact && <TableCell className="hidden sm:table-cell" />}
              <TableCell />
            </TableRow>
          )}
        </TableBody>
      </Table>
    </div>
  )
})

